import React, { useState, useEffect } from 'react';
import { getPayments, createPayment, updatePayment, deletePayment } from '../services/api';
import './Pages.css';

export default function Payments() {
  const [payments, setPayments] = useState([]);
  const [showForm, setShowForm] = useState(false);
  const [filterStatus, setFilterStatus] = useState('');
  const [form, setForm] = useState({
    patientId: '',
    amount: '',
    status: 'pending',
    paymentMethod: '',
    description: ''
  });

  useEffect(() => {
    fetchPayments();
  }, []);

  const fetchPayments = async () => {
    try {
      const res = await getPayments();
      setPayments(res.data);
    } catch (err) {
      console.error('Error:', err);
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      await createPayment(form);
      setForm({
        patientId: '',
        amount: '',
        status: 'pending',
        paymentMethod: '',
        description: ''
      });
      setShowForm(false);
      fetchPayments();
    } catch (err) {
      console.error('Error:', err);
    }
  };

  const handleStatusChange = async (id, status) => {
    try {
      await updatePayment(id, { status });
      fetchPayments();
    } catch (err) {
      console.error('Error:', err);
    }
  };

  const handleDelete = async (id) => {
    if (window.confirm('¿Estás seguro?')) {
      try {
        await deletePayment(id);
        fetchPayments();
      } catch (err) {
        console.error('Error:', err);
      }
    }
  };

  const filtered = filterStatus ? payments.filter((p) => p.status === filterStatus) : payments;

  return (
    <div className="page">
      <h2>💰 Pagos</h2>

      <div className="search-bar">
        <button onClick={() => setShowForm(!showForm)} className="btn-primary">
          {showForm ? 'Cancelar' : '+ Nuevo Pago'}
        </button>
        <select value={filterStatus} onChange={(e) => setFilterStatus(e.target.value)}>
          <option value="">Todos</option>
          <option value="pending">Pendiente</option>
          <option value="paid">Pagado</option>
          <option value="cancelled">Cancelado</option>
        </select>
      </div>

      {showForm && (
        <form onSubmit={handleSubmit} className="form-container">
          <input
            type="text"
            placeholder="ID Paciente"
            value={form.patientId}
            onChange={(e) => setForm({ ...form, patientId: e.target.value })}
            required
          />
          <input
            type="number"
            placeholder="Monto"
            value={form.amount}
            onChange={(e) => setForm({ ...form, amount: e.target.value })}
            step="0.01"
            required
          />
          <select
            value={form.paymentMethod}
            onChange={(e) => setForm({ ...form, paymentMethod: e.target.value })}
          >
            <option value="">Método de pago</option>
            <option value="credit_card">Tarjeta Crédito</option>
            <option value="cash">Efectivo</option>
            <option value="transfer">Transferencia</option>
          </select>
          <textarea
            placeholder="Descripción"
            value={form.description}
            onChange={(e) => setForm({ ...form, description: e.target.value })}
          />
          <button type="submit" className="btn-success">Crear</button>
        </form>
      )}

      <table className="table">
        <thead>
          <tr>
            <th>Referencia</th>
            <th>Monto</th>
            <th>Método</th>
            <th>Estado</th>
            <th>Acciones</th>
          </tr>
        </thead>
        <tbody>
          {filtered.map((p) => (
            <tr key={p.id}>
              <td>{p.referenceNumber}</td>
              <td>${parseFloat(p.amount).toFixed(2)}</td>
              <td>{p.paymentMethod || '-'}</td>
              <td>
                <select
                  value={p.status}
                  onChange={(e) => handleStatusChange(p.id, e.target.value)}
                >
                  <option value="pending">Pendiente</option>
                  <option value="paid">Pagado</option>
                  <option value="cancelled">Cancelado</option>
                </select>
              </td>
              <td>
                <button className="btn-danger" onClick={() => handleDelete(p.id)}>
                  Eliminar
                </button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}
